51|#[test]
52|fn test_find_lists_all_documents() {
53|    let dir = setup_workspace();
54|
55|    write(
56|        dir.path().join("doc1.md"),
57|        indoc! {"
58|            # Document One
59|
60|            Content one.
61|        "},
62|    )
63|    .unwrap();
64|
65|    write(
66|        dir.path().join("doc2.md"),
67|        indoc! {"
68|            # Document Two
69|
70|            Content two.
71|        "},
72|    )
73|    .unwrap();
74|
75|    let (stdout, stderr, success) = run_iwe(dir.path(), &["-f", "json"]);
76|
77|    assert!(success, "stderr: {}", stderr);
78|
79|    let parsed: serde_json::Value = serde_json::from_str(&stdout).expect("valid JSON");
80|    assert_eq!(parsed["total"], 2);
81|
82|    let results = parsed["results"].as_array().unwrap();
83|    let keys: Vec<&str> = results.iter().map(|r| r["key"].as_str().unwrap()).collect();
84|    assert!(keys.contains(&"doc1"));
85|    assert!(keys.contains(&"doc2"));
86|}
