216|fn test_find_limit() {
217|    let dir = setup_workspace();
218|
219|    for i in 1..=10 {
220|        write(
221|            dir.path().join(format!("doc{}.md", i)),
222|            format!("# Document {}\n\nContent.", i),
223|        )
224|        .unwrap();
225|    }
