#[test]
fn test_find_count_combines_with_filters() {
    let dir = setup_workspace();

    write(
        dir.path().join("parent-ready.md"),
        indoc! {"
            ---
            status: ready
            ---

            # Parent Ready

            [child](child)
        "},
    )
    .unwrap();
    write(
        dir.path().join("orphan-ready.md"),
        indoc! {"
            ---
            status: ready
            ---

            # Orphan Ready
        "},
    )
    .unwrap();
    write(
        dir.path().join("orphan-done.md"),
        indoc! {"
            ---
            status: done
            ---

            # Orphan Done
        "},
    )
    .unwrap();
    write(
        dir.path().join("child.md"),
        indoc! {"
            ---
            status: ready
            ---

            # Child
        "},
    )
    .unwrap();

    let (stdout, stderr, success) = run_iwe(
        dir.path(),
        &["--count", "--roots", "--meta", "status=ready"],
    );

    assert!(success, "stderr: {}", stderr);
    assert_eq!(stdout, "2\n");
}

#[test]
fn test_find_count_ignores_limit() {
    let dir = setup_workspace();

